const staticData = $getWorkflowStaticData('global');
staticData.seenMessageIds = staticData.seenMessageIds || {};
const seen = staticData.seenMessageIds;
const now = Date.now();
const retentionMs = 14 * 24 * 60 * 60 * 1000;
for (const [id, timestamp] of Object.entries(seen)) {
  if (now - timestamp > retentionMs) {
    delete seen[id];
  }
}
const output = [];
for (const item of $input.all()) {
  const email = item.json;
  const messageId = email.id || email.message_id || '';
  if (!messageId || seen[messageId]) {
    continue;
  }
  seen[messageId] = now;
  const headers = email.payload && email.payload.headers ? email.payload.headers : [];
  const headerValue = (name) => {
    const found = headers.find((header) => String(header.name || '').toLowerCase() === name.toLowerCase());
    return found ? String(found.value || '') : '';
  };
  const subject = email.subject || email.Subject || headerValue('subject') || '';
  const body = email.text || email.snippet || email.body || '';
  const from = email.from || email.From || headerValue('from') || '';
  const emailMatch = from.match(/<(.+?)>/) || from.match(/([^\s]+@[^\s]+)/);
  const senderEmail = emailMatch ? emailMatch[1] : '';
  const nameMatch = from.match(/^"?([^"<]+)"?\s*</);
  const senderName = nameMatch ? nameMatch[1].trim() : '';
  output.push({ json: { subject, body: String(body).substring(0, 5000), sender_email: senderEmail, sender_name: senderName, raw_from: from, message_id: messageId, thread_id: email.threadId || email.thread_id || '', internal_date: email.internalDate || '' } });
}
return output;

const responses = $input.all().map((item) => item.json);
if (!responses.length) {
  return [];
}
const classifications = $items('Classify Backfill Email').map((item) => item.json);
const emails = $items('Extract Backfill Email Fields').map((item) => item.json);
const updateCandidates = classifications
  .map((classification, index) => ({ classification, email: emails[index] || {} }))
  .filter(({ classification }) => classification.new_status && classification.new_status !== 'Applied' && Number(classification.confidence || 0) > 0.5);
if (!updateCandidates.length) {
  return [];
}
const totalRowsUpdated = responses.reduce((total, response) => total + Number(response.rows_updated || 0), 0);
const lines = updateCandidates.slice(0, 8).map(({ classification, email }) => {
  return '- ' + (classification.company_name || 'Unknown company') + ': ' + classification.new_status + ' | ' + (email.subject || 'No subject');
});
const extra = updateCandidates.length > 8 ? '\n+' + (updateCandidates.length - 8) + ' more' : '';
return [{ json: { content: '**Backfill email updates**\nProcessed status-change emails: ' + updateCandidates.length + '\nRows updated: ' + totalRowsUpdated + '\n' + lines.join('\n') + extra } }];

const classifications = $items('Classify Backfill Email').map((item) => item.json);
const emails = $items('Extract Backfill Email Fields').map((item) => item.json);
const reviewItems = classifications
  .map((classification, index) => ({ classification, email: emails[index] || {} }))
  .filter(({ classification }) => classification.requires_review === true);
if (!reviewItems.length) {
  return [];
}
const lines = reviewItems.slice(0, 8).map(({ classification, email }) => {
  return '- ' + (email.raw_from || 'Unknown sender') + ' | ' + (email.subject || 'No subject') + ' | ' + Math.round(Number(classification.confidence || 0) * 100) + '% | ' + (classification.matched_rule || classification.email_type);
});
const extra = reviewItems.length > 8 ? '\n+' + (reviewItems.length - 8) + ' more' : '';
return [{ json: { content: '**Backfilled job emails need manual review**\nReview count: ' + reviewItems.length + '\n' + lines.join('\n') + extra } }];
